-- Los 12 tickets de práctica de OCSO. Se corre después de esquema.sql.
-- Uno ya está facturado (352-0008720) y otro es de septiembre (217-0044390): sirven para ver los rechazos.
on conflict (folio) do nothing;

-- El ticket que otra persona ya facturó.
do $$
begin
  if not exists (select 1 from public.facturas where folio_ticket = '352-0008720') then
    perform public.facturar_ticket('352-0008720', 162.40,
      '{"rfc":"XOJI740919U48","nombre":"INGRID XODAR JIMENEZ","regimen":"612","uso":"G03","cp":"76028"}'::jsonb, 'portal');
  end if;
end $$;
